#!/bin/bash\n\n# AgentScan Rollback and Recovery Script\n# Provides comprehensive rollback capabilities for all deployment platforms\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels from deployment/scripts\nDEPLOYMENT_DIR=\"$PROJECT_ROOT/deployment\"\n\n# Default configuration\nENVIRONMENT=\"production\"\nPLATFORM=\"kubernetes\"  # kubernetes, docker, digitalocean\nNAMESPACE=\"agentscan\"\nDRY_RUN=false\nVERBOSE=false\nFORCE_ROLLBACK=false\nSKIP_HEALTH_CHECKS=false\nROLLBACK_TIMEOUT=300\nHEALTH_CHECK_TIMEOUT=180\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Rollback and Recovery Script\n\nUsage: $0 [OPTIONS] [COMMAND] [VERSION]\n\nCommands:\n    rollback [version]      Rollback to previous or specific version\n    list-versions          List available versions for rollback\n    status                 Show current deployment status\n    emergency-stop         Emergency stop all services\n    emergency-restore      Restore from emergency backup\n    health-check           Perform comprehensive health checks\n    create-backup          Create deployment backup\n    validate-rollback      Validate rollback target\n\nOptions:\n    --environment ENV       Environment (default: production)\n    --platform PLATFORM    Platform: kubernetes, docker, digitalocean (default: kubernetes)\n    --namespace NS          Kubernetes namespace (default: agentscan)\n    --dry-run              Perform dry run without making changes\n    --verbose              Enable verbose logging\n    --force                Force rollback even if validation fails\n    --skip-health-checks   Skip health checks after rollback\n    --timeout SECONDS      Rollback timeout (default: 300)\n    --health-timeout SEC   Health check timeout (default: 180)\n    --help                 Show this help message\n\nExamples:\n    $0 rollback                    # Rollback to previous version\n    $0 rollback v1.2.2            # Rollback to specific version\n    $0 list-versions               # List available versions\n    $0 emergency-stop              # Emergency stop all services\n    $0 --platform docker rollback # Rollback Docker deployment\n\nEOF\n}\n\n# Function to list available versions\nlist_versions() {\n    log_info \"Available versions for rollback on platform: $PLATFORM\"\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            echo \"=== Deployment History ===\"\n            kubectl rollout history deployment/agentscan-api -n \"$NAMESPACE\" 2>/dev/null || echo \"No API deployment history found\"\n            echo \"\"\n            kubectl rollout history deployment/agentscan-orchestrator -n \"$NAMESPACE\" 2>/dev/null || echo \"No orchestrator deployment history found\"\n            echo \"\"\n            \n            echo \"=== Available ReplicaSets ===\"\n            kubectl get replicasets -n \"$NAMESPACE\" -o wide --sort-by=.metadata.creationTimestamp 2>/dev/null || echo \"No ReplicaSets found\"\n            ;;\n        \"docker\")\n            echo \"=== Docker Images ===\"\n            docker images agentscan/api --format \"table {{.Repository}}\\t{{.Tag}}\\t{{.CreatedAt}}\\t{{.Size}}\" 2>/dev/null || echo \"No API images found\"\n            docker images agentscan/orchestrator --format \"table {{.Repository}}\\t{{.Tag}}\\t{{.CreatedAt}}\\t{{.Size}}\" 2>/dev/null || echo \"No orchestrator images found\"\n            ;;\n        \"digitalocean\")\n            echo \"=== DigitalOcean App Deployments ===\"\n            local app_name=\"agentscan-${ENVIRONMENT}\"\n            doctl apps list-deployments \"$app_name\" 2>/dev/null || echo \"No deployment history found for app: $app_name\"\n            ;;\n    esac\n}\n\n# Function to get current deployment version\nget_current_version() {\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            kubectl get deployment agentscan-api -n \"$NAMESPACE\" -o jsonpath='{.metadata.annotations.deployment\\.kubernetes\\.io/revision}' 2>/dev/null || echo \"unknown\"\n            ;;\n        \"docker\")\n            docker-compose -f \"$DEPLOYMENT_DIR/production/docker-compose.yml\" ps --format \"table {{.Service}}\\t{{.Image}}\" 2>/dev/null | grep api | awk '{print $2}' | cut -d':' -f2 || echo \"unknown\"\n            ;;\n        \"digitalocean\")\n            local app_name=\"agentscan-${ENVIRONMENT}\"\n            doctl apps get \"$app_name\" --format ID --no-header 2>/dev/null || echo \"unknown\"\n            ;;\n    esac\n}\n\n# Function to validate rollback target\nvalidate_rollback_target() {\n    local target_version=\"$1\"\n    \n    log_info \"Validating rollback target: $target_version\"\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Check if revision exists\n            if [[ \"$target_version\" =~ ^[0-9]+$ ]]; then\n                local max_revision=$(kubectl rollout history deployment/agentscan-api -n \"$NAMESPACE\" --output=json 2>/dev/null | jq -r '.items | length' || echo \"0\")\n                if [[ \"$target_version\" -gt \"$max_revision\" ]] || [[ \"$target_version\" -lt 1 ]]; then\n                    log_error \"Invalid revision number: $target_version (available: 1-$max_revision)\"\n                    return 1\n                fi\n            else\n                log_error \"Kubernetes rollback requires numeric revision number\"\n                return 1\n            fi\n            ;;\n        \"docker\")\n            # Check if image tag exists\n            if ! docker image inspect \"agentscan/api:$target_version\" &> /dev/null; then\n                log_error \"Docker image not found: agentscan/api:$target_version\"\n                return 1\n            fi\n            ;;\n        \"digitalocean\")\n            # For DigitalOcean, we'll validate during rollback\n            log_verbose \"DigitalOcean rollback validation will be performed during rollback\"\n            ;;\n    esac\n    \n    log_success \"Rollback target validation passed\"\n    return 0\n}\n\n# Function to create deployment backup\ncreate_backup() {\n    local backup_name=\"backup-$(date +%Y%m%d-%H%M%S)\"\n    local backup_dir=\"$DEPLOYMENT_DIR/backups/$backup_name\"\n    \n    log_info \"Creating deployment backup: $backup_name\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would create backup at $backup_dir\"\n        return 0\n    fi\n    \n    mkdir -p \"$backup_dir\"\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Backup current deployments\n            kubectl get deployment agentscan-api -n \"$NAMESPACE\" -o yaml > \"$backup_dir/api-deployment.yaml\" 2>/dev/null || true\n            kubectl get deployment agentscan-orchestrator -n \"$NAMESPACE\" -o yaml > \"$backup_dir/orchestrator-deployment.yaml\" 2>/dev/null || true\n            \n            # Backup services and ingress\n            kubectl get services -n \"$NAMESPACE\" -o yaml > \"$backup_dir/services.yaml\" 2>/dev/null || true\n            kubectl get ingress -n \"$NAMESPACE\" -o yaml > \"$backup_dir/ingress.yaml\" 2>/dev/null || true\n            \n            # Backup configmaps and secrets\n            kubectl get configmaps -n \"$NAMESPACE\" -o yaml > \"$backup_dir/configmaps.yaml\" 2>/dev/null || true\n            kubectl get secrets -n \"$NAMESPACE\" -o yaml > \"$backup_dir/secrets.yaml\" 2>/dev/null || true\n            ;;\n        \"docker\")\n            # Backup docker-compose configuration\n            cp \"$DEPLOYMENT_DIR/production/docker-compose.yml\" \"$backup_dir/\" 2>/dev/null || true\n            \n            # Export current container configurations\n            docker-compose -f \"$DEPLOYMENT_DIR/production/docker-compose.yml\" config > \"$backup_dir/resolved-compose.yml\" 2>/dev/null || true\n            ;;\n        \"digitalocean\")\n            # Backup app specification\n            local app_name=\"agentscan-${ENVIRONMENT}\"\n            doctl apps get \"$app_name\" --format Spec --output json > \"$backup_dir/app-spec.json\" 2>/dev/null || true\n            ;;\n    esac\n    \n    # Create backup metadata\n    cat > \"$backup_dir/metadata.json\" << EOF\n{\n  \"timestamp\": \"$(date -u +%Y-%m-%dT%H:%M:%SZ)\",\n  \"platform\": \"$PLATFORM\",\n  \"environment\": \"$ENVIRONMENT\",\n  \"namespace\": \"$NAMESPACE\",\n  \"current_version\": \"$(get_current_version)\",\n  \"backup_name\": \"$backup_name\"\n}\nEOF\n    \n    log_success \"Backup created: $backup_dir\"\n    echo \"$backup_dir\"\n}\n\n# Function to perform rollback\nperform_rollback() {\n    local target_version=\"${1:-}\"\n    \n    # If no version specified, rollback to previous\n    if [[ -z \"$target_version\" ]]; then\n        log_info \"No version specified, rolling back to previous version\"\n    else\n        log_info \"Rolling back to version: $target_version\"\n        \n        # Validate target version\n        if ! validate_rollback_target \"$target_version\"; then\n            if [[ \"$FORCE_ROLLBACK\" != \"true\" ]]; then\n                log_error \"Rollback validation failed. Use --force to override.\"\n                return 1\n            else\n                log_warning \"Continuing rollback due to --force flag\"\n            fi\n        fi\n    fi\n    \n    # Create backup before rollback\n    local backup_path\n    backup_path=$(create_backup)\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would perform rollback\"\n        return 0\n    fi\n    \n    # Perform platform-specific rollback\n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            rollback_kubernetes \"$target_version\"\n            ;;\n        \"docker\")\n            rollback_docker \"$target_version\"\n            ;;\n        \"digitalocean\")\n            rollback_digitalocean \"$target_version\"\n            ;;\n    esac\n    \n    # Perform health checks after rollback\n    if [[ \"$SKIP_HEALTH_CHECKS\" != \"true\" ]]; then\n        if ! perform_health_checks; then\n            log_error \"Health checks failed after rollback\"\n            log_error \"Backup available at: $backup_path\"\n            return 1\n        fi\n    fi\n    \n    log_success \"Rollback completed successfully\"\n    log_info \"Backup available at: $backup_path\"\n    return 0\n}\n\n# Function to rollback Kubernetes deployment\nrollback_kubernetes() {\n    local target_version=\"$1\"\n    \n    log_info \"Rolling back Kubernetes deployment...\"\n    \n    if [[ -n \"$target_version\" ]]; then\n        # Rollback to specific revision\n        kubectl rollout undo deployment/agentscan-api -n \"$NAMESPACE\" --to-revision=\"$target_version\"\n        kubectl rollout undo deployment/agentscan-orchestrator -n \"$NAMESPACE\" --to-revision=\"$target_version\"\n    else\n        # Rollback to previous revision\n        kubectl rollout undo deployment/agentscan-api -n \"$NAMESPACE\"\n        kubectl rollout undo deployment/agentscan-orchestrator -n \"$NAMESPACE\"\n    fi\n    \n    # Wait for rollback to complete\n    log_info \"Waiting for rollback to complete...\"\n    kubectl rollout status deployment/agentscan-api -n \"$NAMESPACE\" --timeout=\"${ROLLBACK_TIMEOUT}s\"\n    kubectl rollout status deployment/agentscan-orchestrator -n \"$NAMESPACE\" --timeout=\"${ROLLBACK_TIMEOUT}s\"\n    \n    log_success \"Kubernetes rollback completed\"\n}\n\n# Function to rollback Docker deployment\nrollback_docker() {\n    local target_version=\"$1\"\n    \n    log_info \"Rolling back Docker deployment...\"\n    \n    local compose_file=\"$DEPLOYMENT_DIR/production/docker-compose.yml\"\n    \n    if [[ -n \"$target_version\" ]]; then\n        # Update image tags in compose file\n        export AGENTSCAN_IMAGE_TAG=\"$target_version\"\n        \n        # Pull the target images\n        docker-compose -f \"$compose_file\" pull\n        \n        # Restart services with new images\n        docker-compose -f \"$compose_file\" up -d\n    else\n        log_error \"Docker rollback requires specific version tag\"\n        return 1\n    fi\n    \n    # Wait for services to be healthy\n    log_info \"Waiting for services to be healthy...\"\n    local timeout=$ROLLBACK_TIMEOUT\n    local elapsed=0\n    local interval=10\n    \n    while [[ $elapsed -lt $timeout ]]; do\n        if docker-compose -f \"$compose_file\" ps | grep -q \"Up (healthy)\"; then\n            log_success \"Docker rollback completed\"\n            return 0\n        fi\n        \n        sleep $interval\n        elapsed=$((elapsed + interval))\n        log_verbose \"Waiting for services to be healthy... (${elapsed}s/${timeout}s)\"\n    done\n    \n    log_error \"Docker rollback failed: timeout waiting for services to be healthy\"\n    return 1\n}\n\n# Function to rollback DigitalOcean deployment\nrollback_digitalocean() {\n    local target_version=\"$1\"\n    \n    log_info \"Rolling back DigitalOcean deployment...\"\n    \n    local app_name=\"agentscan-${ENVIRONMENT}\"\n    \n    if [[ -n \"$target_version\" ]]; then\n        # Rollback to specific deployment\n        if ! doctl apps create-deployment \"$app_name\" --deployment-id=\"$target_version\" --wait; then\n            log_error \"Failed to rollback to deployment: $target_version\"\n            return 1\n        fi\n    else\n        log_error \"DigitalOcean rollback requires specific deployment ID\"\n        log_info \"Use 'list-versions' command to see available deployments\"\n        return 1\n    fi\n    \n    log_success \"DigitalOcean rollback completed\"\n}\n\n# Function to perform health checks\nperform_health_checks() {\n    log_info \"Performing post-rollback health checks...\"\n    \n    local health_endpoints=()\n    local timeout=$HEALTH_CHECK_TIMEOUT\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Check if pods are ready\n            if ! kubectl wait --for=condition=ready pod -l app=agentscan-api -n \"$NAMESPACE\" --timeout=\"${timeout}s\"; then\n                log_error \"API pods not ready after rollback\"\n                return 1\n            fi\n            \n            if ! kubectl wait --for=condition=ready pod -l app=agentscan-orchestrator -n \"$NAMESPACE\" --timeout=\"${timeout}s\"; then\n                log_error \"Orchestrator pods not ready after rollback\"\n                return 1\n            fi\n            \n            # Get service endpoints for health checks\n            local api_service=$(kubectl get service agentscan-api -n \"$NAMESPACE\" -o jsonpath='{.spec.clusterIP}' 2>/dev/null || echo \"\")\n            if [[ -n \"$api_service\" ]]; then\n                health_endpoints+=(\"http://${api_service}:8080/health\")\n            fi\n            ;;\n        \"docker\")\n            health_endpoints+=(\"http://localhost:8080/health\")\n            health_endpoints+=(\"http://localhost:8081/health\")\n            ;;\n        \"digitalocean\")\n            local app_url=$(doctl apps get \"agentscan-${ENVIRONMENT}\" --format LiveURL --no-header 2>/dev/null || echo \"\")\n            if [[ -n \"$app_url\" ]]; then\n                health_endpoints+=(\"${app_url}/health\")\n            fi\n            ;;\n    esac\n    \n    # Perform HTTP health checks\n    local failed_checks=()\n    \n    for endpoint in \"${health_endpoints[@]}\"; do\n        log_verbose \"Checking health endpoint: $endpoint\"\n        \n        local retries=0\n        local max_retries=$((timeout / 10))\n        local success=false\n        \n        while [[ $retries -lt $max_retries ]]; do\n            if curl -f -s --max-time 10 \"$endpoint\" > /dev/null 2>&1; then\n                log_success \"Health check passed: $endpoint\"\n                success=true\n                break\n            fi\n            \n            sleep 10\n            ((retries++))\n            log_verbose \"Health check retry $retries/$max_retries for $endpoint\"\n        done\n        \n        if [[ \"$success\" != \"true\" ]]; then\n            failed_checks+=(\"$endpoint\")\n        fi\n    done\n    \n    if [[ ${#failed_checks[@]} -gt 0 ]]; then\n        log_error \"Health checks failed for endpoints:\"\n        printf '  %s\\n' \"${failed_checks[@]}\"\n        return 1\n    fi\n    \n    log_success \"All health checks passed\"\n    return 0\n}\n\n# Function to emergency stop all services\nemergency_stop() {\n    log_warning \"Performing emergency stop of all services...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would perform emergency stop\"\n        return 0\n    fi\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Scale down all deployments to 0\n            kubectl scale deployment --all --replicas=0 -n \"$NAMESPACE\"\n            \n            # Wait for pods to terminate\n            kubectl wait --for=delete pod --all -n \"$NAMESPACE\" --timeout=60s || true\n            ;;\n        \"docker\")\n            # Stop all services\n            local compose_file=\"$DEPLOYMENT_DIR/production/docker-compose.yml\"\n            docker-compose -f \"$compose_file\" stop\n            ;;\n        \"digitalocean\")\n            log_warning \"DigitalOcean emergency stop not implemented - use DigitalOcean console\"\n            ;;\n    esac\n    \n    log_success \"Emergency stop completed\"\n}\n\n# Function to emergency restore from backup\nemergency_restore() {\n    local backup_name=\"${1:-}\"\n    \n    if [[ -z \"$backup_name\" ]]; then\n        log_error \"Backup name is required for emergency restore\"\n        log_info \"Available backups:\"\n        ls -la \"$DEPLOYMENT_DIR/backups/\" 2>/dev/null || echo \"No backups found\"\n        return 1\n    fi\n    \n    local backup_dir=\"$DEPLOYMENT_DIR/backups/$backup_name\"\n    \n    if [[ ! -d \"$backup_dir\" ]]; then\n        log_error \"Backup not found: $backup_dir\"\n        return 1\n    fi\n    \n    log_warning \"Performing emergency restore from backup: $backup_name\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would restore from backup $backup_dir\"\n        return 0\n    fi\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            # Restore deployments\n            if [[ -f \"$backup_dir/api-deployment.yaml\" ]]; then\n                kubectl apply -f \"$backup_dir/api-deployment.yaml\"\n            fi\n            \n            if [[ -f \"$backup_dir/orchestrator-deployment.yaml\" ]]; then\n                kubectl apply -f \"$backup_dir/orchestrator-deployment.yaml\"\n            fi\n            \n            # Wait for deployments to be ready\n            kubectl wait --for=condition=available --timeout=300s deployment --all -n \"$NAMESPACE\"\n            ;;\n        \"docker\")\n            # Restore docker-compose configuration\n            if [[ -f \"$backup_dir/docker-compose.yml\" ]]; then\n                cp \"$backup_dir/docker-compose.yml\" \"$DEPLOYMENT_DIR/production/\"\n                docker-compose -f \"$DEPLOYMENT_DIR/production/docker-compose.yml\" up -d\n            fi\n            ;;\n        \"digitalocean\")\n            # Restore app specification\n            if [[ -f \"$backup_dir/app-spec.json\" ]]; then\n                local app_name=\"agentscan-${ENVIRONMENT}\"\n                doctl apps update \"$app_name\" --spec \"$backup_dir/app-spec.json\" --wait\n            fi\n            ;;\n    esac\n    \n    log_success \"Emergency restore completed\"\n}\n\n# Function to show current status\nshow_status() {\n    log_info \"Current deployment status for platform: $PLATFORM\"\n    \n    echo \"Current version: $(get_current_version)\"\n    echo \"Environment: $ENVIRONMENT\"\n    echo \"Platform: $PLATFORM\"\n    echo \"Namespace: $NAMESPACE\"\n    echo \"\"\n    \n    case \"$PLATFORM\" in\n        \"kubernetes\")\n            echo \"=== Deployment Status ===\"\n            kubectl get deployments -n \"$NAMESPACE\" -o wide 2>/dev/null || echo \"No deployments found\"\n            echo \"\"\n            \n            echo \"=== Pod Status ===\"\n            kubectl get pods -n \"$NAMESPACE\" -o wide 2>/dev/null || echo \"No pods found\"\n            ;;\n        \"docker\")\n            echo \"=== Docker Compose Status ===\"\n            local compose_file=\"$DEPLOYMENT_DIR/production/docker-compose.yml\"\n            if [[ -f \"$compose_file\" ]]; then\n                docker-compose -f \"$compose_file\" ps\n            else\n                echo \"Docker compose file not found\"\n            fi\n            ;;\n        \"digitalocean\")\n            echo \"=== DigitalOcean App Status ===\"\n            local app_name=\"agentscan-${ENVIRONMENT}\"\n            doctl apps get \"$app_name\" 2>/dev/null || echo \"App not found: $app_name\"\n            ;;\n    esac\n}\n\n# Parse command line arguments\nCOMMAND=\"rollback\"\nTARGET_VERSION=\"\"\n\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        rollback|list-versions|status|emergency-stop|emergency-restore|health-check|create-backup|validate-rollback)\n            COMMAND=\"$1\"\n            shift\n            ;;\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --platform)\n            PLATFORM=\"$2\"\n            shift 2\n            ;;\n        --namespace)\n            NAMESPACE=\"$2\"\n            shift 2\n            ;;\n        --dry-run)\n            DRY_RUN=true\n            shift\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --force)\n            FORCE_ROLLBACK=true\n            shift\n            ;;\n        --skip-health-checks)\n            SKIP_HEALTH_CHECKS=true\n            shift\n            ;;\n        --timeout)\n            ROLLBACK_TIMEOUT=\"$2\"\n            shift 2\n            ;;\n        --health-timeout)\n            HEALTH_CHECK_TIMEOUT=\"$2\"\n            shift 2\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            # Handle version argument for rollback and emergency-restore commands\n            if [[ \"$COMMAND\" == \"rollback\" ]] || [[ \"$COMMAND\" == \"emergency-restore\" ]] || [[ \"$COMMAND\" == \"validate-rollback\" ]]; then\n                TARGET_VERSION=\"$1\"\n                shift\n            else\n                log_error \"Unknown option: $1\"\n                show_help\n                exit 1\n            fi\n            ;;\n    esac\ndone\n\n# Execute command\ncase \"$COMMAND\" in\n    \"rollback\")\n        perform_rollback \"$TARGET_VERSION\"\n        ;;\n    \"list-versions\")\n        list_versions\n        ;;\n    \"status\")\n        show_status\n        ;;\n    \"emergency-stop\")\n        emergency_stop\n        ;;\n    \"emergency-restore\")\n        emergency_restore \"$TARGET_VERSION\"\n        ;;\n    \"health-check\")\n        perform_health_checks\n        ;;\n    \"create-backup\")\n        create_backup\n        ;;\n    \"validate-rollback\")\n        validate_rollback_target \"$TARGET_VERSION\"\n        ;;\n    *)\n        log_error \"Unknown command: $COMMAND\"\n        show_help\n        exit 1\n        ;;\nesac"